package main

import "fmt"

// This demonstrates a well-structured Go application's dependency injection
// pattern typically found in cmd/api/main.go

// --- Domain Layer ---
type User struct {
	ID   int
	Name string
}

type UserRepository interface {
	FindAll() ([]*User, error)
}

// --- Repository Layer ---
type InMemoryUserRepo struct {
	users []*User
}

func NewInMemoryUserRepo() *InMemoryUserRepo {
	return &InMemoryUserRepo{
		users: []*User{
			{ID: 1, Name: "Alice"},
			{ID: 2, Name: "Bob"},
		},
	}
}

func (r *InMemoryUserRepo) FindAll() ([]*User, error) {
	return r.users, nil
}

// --- Service Layer ---
type UserService struct {
	repo UserRepository
}

func NewUserService(repo UserRepository) *UserService {
	return &UserService{repo: repo}
}

func (s *UserService) ListUsers() ([]*User, error) {
	// TODO: add business logic (e.g., filtering, sorting)
	return s.repo.FindAll()
}

// --- Main (Composition Root) ---
func main() {
	// Dependency injection: wire everything together
	repo := NewInMemoryUserRepo()
	svc := NewUserService(repo)

	users, err := svc.ListUsers()
	if err != nil {
		fmt.Println("Error:", err)
		return
	}

	for _, u := range users {
		fmt.Printf("User %d: %s\n", u.ID, u.Name)
	}
}
